from author_tools import *
N(bank,5,201,C,'Натуральные числа и разрядная запись','14',[
('5-place-value','В числе 407305 найдите цифру разряда тысяч.',7,'Считаем разряды справа: единицы 5, десятки 0, сотни 3, тысячи 7.','407305//1000%10','b'),
('5-value-of-digit','На сколько уменьшится число 5832, если цифру 8 заменить цифрой 3?',500,'Цифра 8 стоит в разряде сотен. Уменьшение на 5 сотен равно 500.','5832-5332','b'),
('5-restore-place-sum','Число состоит из 6 тысяч, 12 сотен и 4 единиц. Найдите это число.',7204,'12 сотен — 1200. Складываем 6000 + 1200 + 4 = 7204. Разрядных единиц может быть больше девяти до приведения записи.','6*1000+12*100+4','m'),
('5-total-tens','Сколько полных десятков содержится в числе 438?',43,'438 = 43 · 10 + 8. Полных десятков 43; цифра десятков 3 отвечает другому вопросу.','438//10','m',{'tricky':True}),
('5-append-digit','К натуральному числу справа приписали ноль. Число увеличилось на 459. Найдите исходное число.',51,'После приписывания нуля число стало в 10 раз больше. Разность составляет 9 исходных чисел: 459 : 9 = 51.','459/9','h'),
('5-leading-zero-choice','Из цифр 0, 2, 5, 8 составьте наименьшее четырёхзначное число без повторений. Найдите его.',2058,'Первая цифра не ноль. Берём наименьшую ненулевую 2, затем остальные в порядке возрастания: 0, 5, 8.','min(1000*a+100*b+10*c+d for a,b,c,d in permutations([0,2,5,8]) if a!=0)','h'),
('5-swap-adjacent','В числе 4627 поменяли местами цифры сотен и десятков. На сколько уменьшилось число?',360,'Получилось 4267. Разность 4627 − 4267 = 360. Перестановка цифр не означает перестановку самих разрядов.','4627-4267','m'),
('5-reverse-two-digit','Двузначное число оканчивается цифрой 2. После перестановки цифр оно уменьшилось на 45. Найдите исходное число.',72,'Разность чисел равна девятикратной разности цифр. Разность цифр 45 : 9 = 5, цифра десятков 2 + 5 = 7. Число 72.','[n for n in range(10,100) if n%10==2 and n-(n%10*10+n//10)==45][0]','s',{'tricky':True}),
('5-between-consecutive-hundreds','Число больше 390, меньше 410 и содержит ровно два нуля. Найдите его.',400,'Среди чисел между 390 и 410 только 400 имеет два нуля. Неравенства строгие, но это не исключает 400.','[n for n in range(391,410) if str(n).count("0")==2][0]','h'),
('5-odometer-carry','Счётчик показывает 00999. После каждого шага число увеличивается на единицу, сохраняются пять позиций. Сколько позиций изменится на следующем шаге?',4,'Следующее показание 01000. Изменятся сотни, десятки, единицы и позиция тысяч; крайний левый ноль останется.','sum(a!=b for a,b in zip("00999","01000"))','s',{'tricky':True})])
N(bank,5,202,C,'Сравнение, округление и оценка','14',[
('5-round-tens','Округлите 734 до десятков.',730,'Цифра единиц 4 меньше 5, поэтому оставляем 73 десятка и заменяем единицы нулём.','round(734/10)*10','b'),
('5-round-hundreds-tie','Округлите 2850 до сотен. При ровно половине сотни округляйте вверх.',2900,'Число находится ровно посередине между 2800 и 2900. По указанному правилу выбираем 2900.','floor(2850/100+.5)*100','b'),
('5-round-preimage','Сколько натуральных чисел при округлении до десятков дают 70? Половину десятка округляют вверх.',10,'Подходят числа от 65 до 74 включительно. Их 74 − 65 + 1 = 10.','len([n for n in range(1,100) if floor(n/10+.5)*10==70])','m'),
('5-round-upper-error','Натуральное число округлили до сотен и получили 500. Какое наибольшее исходное число возможно? Половину сотни округляют вверх.',549,'Числа от 450 до 549 округляются до 500. Число 550 округлится уже до 600, поэтому максимум 549.','max(n for n in range(1000) if floor(n/100+.5)*100==500)','h'),
('5-compare-length-mixed','Что больше: 2 м 8 см или 208 см? В ответе укажите разность большей и меньшей длины в сантиметрах.',0,'2 м 8 см = 200 + 8 = 208 см. Длины равны, их разность ноль.','abs(2*100+8-208)','m',{'tricky':True}),
('5-estimate-product-bound','Не выполняя умножение столбиком, определите, сколько тысяч полностью содержится в произведении 199 · 5.',0,'199 · 5 меньше 200 · 5 = 1000. Значит полной тысячи в произведении нет.','(199*5)//1000','m'),
('5-double-rounding','Число 1499 сначала округлили до сотен, затем полученный результат до тысяч. На сколько результат больше округления исходного числа сразу до тысяч? Половину округляют вверх.',1000,'Первый путь: 1499 → 1500 → 2000. Прямое округление: 1499 → 1000. Разность 1000; повторное округление может изменить результат.','floor((floor(1499/100+.5)*100)/1000+.5)*1000-floor(1499/1000+.5)*1000','s',{'tricky':True}),
('5-integer-gap','Между двумя натуральными числами находится ровно 17 других натуральных чисел. Меньшее число равно 24. Найдите большее.',42,'Если между концами 17 чисел, разность концов 18. Большее число 24 + 18 = 42.','24+17+1','h'),
('5-inequality-digit','В записи 4□8 вместо квадратика стоит одна цифра. Число больше 457, но меньше 480. Найдите сумму всех подходящих цифр.',18,'Подходят 458, 468, 478, то есть цифры 5, 6, 7. Сумма 18.','sum(d for d in range(10) if 457<408+10*d<480)','h'),
('5-round-min-interval','Известно, что натуральное число больше 999 и меньше 1101. Какое наименьшее значение может получиться после округления этого числа до сотен?',1000,'Допустимы числа от 1000 до 1100. Наименьшие округляются до 1000, меньший результат невозможен.','min(floor(n/100+.5)*100 for n in range(1000,1101))','m')])
N(bank,5,203,C,'Свойства действий и удобные вычисления','14',[
('5-regroup-sum','Вычислите 37 + 48 + 63 + 52.',200,'Сгруппируем дополняющие до сотни числа: 37 + 63 = 100, 48 + 52 = 100. Всего 200.','37+48+63+52','b'),
('5-distribute-difference','Вычислите 48 · 25 − 8 · 25.',1000,'Выносим общий множитель: (48 − 8) · 25 = 40 · 25 = 1000.','48*25-8*25','m'),
('5-factor-pair-cancel','Вычислите 125 · 16 · 5.',10000,'Можно сначала 125 · 8 = 1000. Тогда 125 · 16 · 5 = 1000 · 2 · 5 = 10000.','125*16*5','m'),
('5-compensation-subtraction','Вычислите 10003 − 4998.',5005,'Вычтем 5000 и вернём лишние 2: 10003 − 5000 + 2 = 5005.','10003-4998','b'),
('5-quotient-invariant','Делимое увеличили в 6 раз, а делитель — в 3 раза. Первоначальное частное равно 14. Найдите новое частное.',28,'Частное увеличится в 6 : 3 = 2 раза. Получим 28. Увеличение делителя само по себе уменьшает частное.','14*6/3','h'),
('5-reconstruct-missing-addend','Из суммы трёх чисел вычли первое и получили 37, вычли второе — 42, вычли третье — 45. Найдите сумму трёх чисел.',62,'Сложение трёх результатов дважды учитывает каждое число. Поэтому искомая сумма (37 + 42 + 45) : 2 = 62.','(37+42+45)/2','s',{'tricky':True}),
('5-erroneous-multiplier','При умножении числа на 7 ученик по ошибке умножил его на 9 и получил результат на 84 больше верного. Найдите верный результат.',294,'Лишние два множителя дают 84, само число 42. Верное произведение 42 · 7 = 294.','84/(9-7)*7','h'),
('5-subtraction-change-both','Уменьшаемое увеличили на 23, а вычитаемое уменьшили на 17. Исходная разность равна 60. Найдите новую разность.',100,'Первое изменение увеличивает разность на 23, второе — ещё на 17. Получаем 60 + 23 + 17 = 100.','60+23+17','m'),
('5-zero-product-equation','Произведение (n − 4) · 17 равно нулю. Найдите натуральное n.',4,'Поскольку 17 не ноль, нулём должен быть множитель n − 4. Следовательно n = 4.','4','m'),
('5-product-two-changes','Произведение двух натуральных чисел равно 180. Первый множитель уменьшили в 3 раза, второй увеличили в 5 раз. Найдите новое произведение.',300,'Общий множитель изменения 5/3. Сначала 180 : 3 = 60, затем 60 · 5 = 300.','180/3*5','h')])
N(bank,5,204,C,'Деление с остатком: ограничения и обратные задачи','14',[
('5-remainder-max','Какой наибольший остаток возможен при делении натурального числа на 12?',11,'Остаток неотрицателен и меньше делителя. Самый большой — 11.','12-1','b'),
('5-divisor-from-division','При делении 94 на неизвестный делитель получили неполное частное 7 и остаток 3. Найдите делитель.',13,'Полные группы содержат 94 − 3 = 91. Делим на семь групп: 91 : 7 = 13. Проверка остатка: 3 < 13.','(94-3)/7','m'),
('5-unknown-remainder-bound','При делении числа на 8 получили неполное частное 6. Найдите наибольшее возможное делимое.',55,'Делимое 8 · 6 + r, где r не больше 7. Максимум 48 + 7 = 55.','8*6+7','m'),
('5-same-quotient-count','Сколько натуральных чисел при делении на 9 дают неполное частное 4?',9,'Это числа 36, 37, …, 44: каждому остатку от 0 до 8 соответствует одно число. Всего 9.','len([n for n in range(1,100) if n//9==4])','h'),
('5-remainder-impossible','Ученик записал 58 = 7 · 7 + 9 как деление с остатком. Найдите правильный остаток при делении 58 на 7.',2,'Равенство верно, но 9 не является допустимым остатком: 9 = 7 + 2. Получаем 58 = 7 · 8 + 2.','58%7','m',{'tricky':True}),
('5-consecutive-multiples-distance','Число находится между соседними кратными 11. До меньшего кратного от него 4 единицы. Сколько единиц до большего?',7,'Соседние кратные отличаются на 11. Уже пройдено 4, осталось 11 − 4 = 7.','11-4','b'),
('5-remainder-sum-carry','Два натуральных числа при делении на 8 дают остатки 5 и 6. Найдите остаток от деления их суммы на 8.',3,'Полные восьмёрки не влияют на остаток. Остаточные части дают 11 = 8 + 3. Ответ 3.','(5+6)%8','h'),
('5-largest-three-digit-multiple','Найдите наибольшее трёхзначное число, которое делится на 37 без остатка.',999,'37 · 27 = 999. Это наибольшее трёхзначное число, поэтому большего подходящего быть не может.','999//37*37','m'),
('5-remainder-double','При делении натурального n на 9 остаток равен 7. Найдите остаток от деления 2n на 9.',5,'Удвоенная остаточная часть 14 = 9 + 5. Полные девятки после удвоения по-прежнему делятся на 9.','2*7%9','h'),
('5-divisor-remainder-equals-quotient','Сколько натуральных делителей d позволяют разделить 47 с неполным частным 5 и остатком 5?',0,'Равенство деления имело бы вид 47 = 5d + 5, то есть 5d = 42. Натурального d нет, поэтому допустимых делителей 0.','len([d for d in range(1,48) if divmod(47,d)==(5,5)])','s',{'tricky':True})])
N(bank,5,205,W,'Покупки, стоимость и сдача','15',[
('5-cost-two-goods','Купили 3 тетради по 28 рублей и ручку за 46 рублей. Сколько рублей заплатили?',130,'Тетради стоят 3 · 28 = 84 рубля. Вместе с ручкой 84 + 46 = 130 рублей.','3*28+46','b'),
('5-change-denomination','За покупку стоимостью 368 рублей дали 500 рублей. Сдачу выдали монетами по 2 рубля. Сколько монет получили?',66,'Сдача 132 рубля. Число двухрублёвых монет 132 : 2 = 66.','(500-368)/2','m'),
('5-budget-max-count','У Саши 250 рублей. Он должен оставить 40 рублей на проезд. Сколько булочек по 32 рубля он может купить максимум?',6,'На булочки доступно 210 рублей. 6 стоят 192, а 7 стоят 224 и превышают бюджет.','(250-40)//32','m'),
('5-gift-bundle','Одна наклейка стоит 15 рублей. При покупке каждых четырёх наклеек пятую дают бесплатно. Какую наименьшую сумму нужно заплатить, чтобы получить не менее 12 наклеек?',150,'За 8 оплаченных дадут 10 наклеек, ещё две надо оплатить. Всего оплачены 10, получены 12, цена 150 рублей. За 9 оплаченных получилось бы только 11.','min(p*15 for p in range(1,20) if p+p//4>=12)','s',{'tricky':True}),
('5-price-from-change','За четыре одинаковых блокнота дали 500 рублей и получили 140 рублей сдачи. Сколько стоит один блокнот?',90,'Покупка стоила 360 рублей. Делим на четыре одинаковых блокнота: 90 рублей.','(500-140)/4','b'),
('5-price-comparison-unit','Упаковка из 6 карандашей стоит 90 рублей, из 10 — 140 рублей. На сколько рублей один карандаш во второй упаковке дешевле?',1,'В первой упаковке цена за штуку 15 рублей, во второй 14. Разность 1 рубль. Сравнивать только цены упаковок нельзя.','90/6-140/10','h'),
('5-split-total-cost','Два друга поровну оплачивают билеты. Первый внёс 700 рублей, второй 300. Сколько рублей второй должен передать первому, чтобы расходы стали равными?',200,'Общие расходы 1000, доля каждого 500. Первый переплатил 200, второй недоплатил 200. Передать нужно 200, а не разность взносов 400.','(700-300)/2','s',{'tricky':True}),
('5-package-integer-choice','Печенье продают упаковками по 6 штук за 70 рублей и по 4 штуки за 50 рублей. Нужно купить ровно 16 штук. Какова наименьшая стоимость?',190,'Возможны четыре упаковки по 4 за 200 рублей или две по 6 и одна по 4 за 190. Второй вариант дешевле.','min(70*a+50*b for a in range(5) for b in range(5) if 6*a+4*b==16)','h'),
('5-cost-difference-infer','Пять одинаковых альбомов стоят на 120 рублей дороже трёх таких альбомов. Сколько стоят четыре альбома?',240,'Разница — цена двух альбомов, значит один стоит 60 рублей. Четыре стоят 240.','120/(5-3)*4','m'),
('5-refundable-container','Бутылка вместе с напитком стоит 80 рублей. За каждую пустую бутылку возвращают 10 рублей. Купили 6 бутылок и вернули все пустые. Найдите окончательные расходы в рублях.',420,'Заплатили 480 рублей, вернули 60. Расходы 420 рублей. Возврат — уменьшение расходов, а не новая покупка.','6*80-6*10','m')])
